<?php require_once __DIR__.'/includes/auth.php';$page_title='Packages';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$name=trim($_POST['name']??'');$price=(float)($_POST['price']??0);$days=(int)($_POST['validity_days']??90);if($name===''||$price<=0||$days<1)flash('error','Enter valid package values.');else{db()->prepare('INSERT INTO packages(name,description,price,validity_days,daily_profit,total_return,status,created_at) VALUES(?,?,?,?,?,?,"ACTIVE",NOW())')->execute([$name,trim($_POST['description']??''),$price,$days,(float)($_POST['daily_profit']??0),(float)($_POST['total_return']??0)]);log_activity('Package created',(int)$admin['id']);flash('success','Package created.');go('packages.php');}}$rows=db()->query('SELECT * FROM packages ORDER BY id DESC')->fetchAll();include __DIR__.'/includes/header.php';?><div class="page-title"><div><h1>Packages / Items</h1><p>Manage public package values from the database.</p></div></div><section class="panel"><h2>Add package</h2><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><div class="form-grid"><div class="field"><label>NAME</label><input class="input" name="name" required></div><div class="field"><label>PRICE</label><input class="input" type="number" min="1" name="price" required></div><div class="field"><label>VALIDITY DAYS</label><input class="input" type="number" min="1" name="validity_days" value="90"></div><div class="field"><label>DAILY SIMULATED REWARD</label><input class="input" type="number" min="0" name="daily_profit"></div><div class="field"><label>TOTAL SIMULATED RETURN</label><input class="input" type="number" min="0" name="total_return"></div><div class="field"><label>DESCRIPTION</label><textarea class="textarea" name="description"></textarea></div></div><button class="button button-primary">ADD PACKAGE</button></form></section><section class="panel"><h2>Configured packages</h2><div class="table-wrap"><table class="table"><thead><tr><th>NAME</th><th>PRICE</th><th>VALIDITY</th><th>STATUS</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?=e($r['name'])?></strong><br><?=e($r['description'])?></td><td><?=money($r['price'])?></td><td><?=$r['validity_days']?> days</td><td><span class="status <?=strtolower(e($r['status']))?>"><?=e($r['status'])?></span></td></tr><?php endforeach;?></tbody></table></div></section><?php include __DIR__.'/includes/footer.php';?>
